                'com.microsoft.sqlserver.jdbc.SQLServerDriver': {
                    label: 'SQLServer',
                    dependentValue: 'JDBC',
                },
                'com.sybase.jdbc3.jdbc.SybDriver': {
                    label: 'Sybase',
                    dependentValue: 'JDBC',
                    inactive: true,
                },
                CSV: {
                    label: 'CSV',
                    dependentValue: 'File',
                },
                'CSV (tab)': {
                    label: 'CSV (tab)',
                    dependentValue: 'File',
                },
                'Custom (Parse by Script)': {
                    label: 'Custom (Parse by Script)',
                    dependentValue: 'File',
                },
                Excel: {
                    label: 'Excel (.xlsx/.xls)',
                    dependentValue: 'File',
                },
                JSON: {
                    label: 'JSON',
                    dependentValue: 'REST',
                },
                'oracle.jdbc.OracleDriver': {
                    label: 'Oracle',
                    dependentValue: 'JDBC',
                },
                'org.mariadb.jdbc.Driver': {
                    label: 'MySQL',
                    dependentValue: 'JDBC',
                },
                XML: {
                    label: 'XML',
                    dependentValue: 'File',
                },
